        ink('16:1', '"OBSERVE THE MONTH OF AVIV" — the chapter\'s first word the one infinitive absolute %s; "the month of Aviv" %s (Exodus 23:15, 34:18 the twins — 16:1\'s closest kin %s)' % (INF_ABS, P('חדש', 'האביב', books=None), KINC[1][0]))
